p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+chr(10),encoding="utf-8")
nl=chr(10)
parts=["# Aethon v7 발표자 노트","","*기준일 2026-10-28 · 미리캔버스 네이티브 구성과 10쪽 최종 수정 반영 · 발표 8분 / 질의 7분*","","본문 16장 발화 계획 7분 10초, 장 전환과 영상 재생 여유 50초. 실제 리허설로 계측한다. 부록은 질의 때 사용한다.",""]
for item in d["slides"]:
    t=str(item["seconds"])+"초" if item["seconds"] else "부록 · 질의용"
    parts.extend(["## "+str(item["id"])+". "+item["title"]+" ("+t+")","",item["speaker_note"],""])
(base/"발표자노트.md").write_text(nl.join(parts)+nl,encoding="utf-8")
total=sum(slide["seconds"] for slide in d["slides"] if slide["section"]=="본문")
assert total==430, "본문 합계가 430초와 다릅니다: " + str(total)
print("본문 "+str(total)+"초, 남는 시간 "+str(480-total)+"초")

